 UPDATE
		TBL_BOARD_M SET board_is_deleted_yn = 'Y' WHERE board_sq = #{boardSq} AND user_sq =
		#{userSq}

mapper.select:
SELECT b.board_sq AS sq, CASE WHEN b.board_type_cd = 1402 THEN 'qna' ELSE 'board' END AS boardType, b.board_ttl AS ttl, COALESCE(u.user_nickname, '탈퇴한 사용자') AS userNickname, b.board_view_cnt AS viewCnt, b.board_comment_cnt AS commentCnt, b.board_recommend_cnt AS recommendCnt, b.board_created_at_dtm AS createdAt, (b.board_view_cnt * 1 + b.board_comment_cnt * 2 + b.board_recommend_cnt * 3) AS score FROM TBL_BOARD_M b LEFT JOIN TBL_USER_M u ON u.user_sq = b.user_sq AND u.user_is_deleted_yn = 'N' WHERE b.board_is_deleted_yn = 'N' AND b.board_type_cd IN (1401, 1402)
AND b.board_created_at_dtm >= DATE_SUB(NOW(), INTERVAL 1 DAY) AND b.board_created_at_dtm >= DATE_SUB(NOW(), INTERVAL 7 DAY) AND b.board_created_at_dtm >= DATE_SUB(NOW(), INTERVAL 30 DAY)
ORDER BY score DESC, b.board_created_at_dtm DESC LIMIT #{size}
